#!/usr/bin/env dotnet
// Find the earliest Friday the 13th and count them in a 400-year cycle
// using the proleptic Gregorian calendar.

// Find the earliest Friday the 13th starting from 0001-01-01
var date = new DateTime(1, 1, 13); // start checking the 13th of each month
while (date.DayOfWeek != DayOfWeek.Friday)
    date = date.AddMonths(1);

Console.WriteLine($"Earliest Friday the 13th: {date:yyyy-MM-dd} ({date.DayOfWeek})");

// Count Friday the 13ths in a full 400-year Gregorian cycle (0001-01-13 to 0400-12-13)
int count = 0;
var current = new DateTime(1, 1, 13);
var end = new DateTime(400, 12, 13);
while (current <= end)
{
    if (current.DayOfWeek == DayOfWeek.Friday)
        count++;
    current = current.AddMonths(1);
}

Console.WriteLine($"Friday the 13ths in a 400-year cycle: {count}");
Console.WriteLine($"Average per year: {count / 400.0:F4}");

// Bonus: which day of the week is most likely to fall on the 13th?
var dayCounts = new int[7];
current = new DateTime(1, 1, 13);
while (current <= end)
{
    dayCounts[(int)current.DayOfWeek]++;
    current = current.AddMonths(1);
}

Console.WriteLine("\n13th falls on each day of the week (400-year cycle):");
foreach (DayOfWeek day in Enum.GetValues<DayOfWeek>())
    Console.WriteLine($"  {day,-9}: {dayCounts[(int)day]} times");
EOF
